dslRule:
@id: string.isnull.or.isblank
@severity: INFO
$str == null :: instanceof($str, "java.lang.String") && sourceVersionGE(11)
=>
$str == null || $str.isBlank()
;;

beforeExample:
class Example {
    String s;
    void foo() {
        if (s == null) {
            System.out.println("String is null");
        }
    }
    void bar(String text) {
        if (text == null) {
            System.out.println("Text is null");
        }
    }
}

afterExample:
class Example {
    String s;
    void foo() {
        if (s == null || s.isBlank()) {
            System.out.println("String is null");
        }
    }
    void bar(String text) {
        if (text == null || text.isBlank()) {
            System.out.println("Text is null");
        }
    }
}

negativeExample:
class Example {
    Integer i;
    void baz(Object o) {
        if (i == null) { // Should not match due to type (Integer)
            System.out.println("Integer is null");
        }
        if (o == null) { // Should not match due to type (Object)
            System.out.println("Object is null");
        }
    }
    // This method would not be matched if the project source version was < 11
    // as required by the sourceVersionGE(11) guard.
    void legacyMethod(String oldStr) {
        if (oldStr == null) { // Would not match if sourceVersionLE(10) was true
             System.out.println("Old string is null");
        }
    }
}
